// Un elemento por adjunto que parezca factura, con un nombre de archivo ordenable.
// PDF, XML y ZIP siempre pasan: la factura electrónica colombiana suele llegar como PDF + XML dentro de un ZIP.
// Las imágenes (PNG, JPG, WEBP) solo pasan si pesan al menos MIN_KB_IMAGEN y su nombre no parece un logo,
// una firma o un ícono de red social: hay proveedores que envían la factura como captura de pantalla.
const MIN_KB_IMAGEN = 50; // Súbelo si se cuelan logos; bájalo si tus proveedores envían capturas pequeñas

const DOCS_OK = ['.pdf', '.xml', '.zip'];
const IMG_EXT = ['.png', '.jpg', '.jpeg', '.webp'];
const NOMBRES_BASURA = /(logo|firma|signature|banner|^image\d+|^outlook-|facebook|linkedin|instagram)/i;

// n8n guarda fileSize como texto («12.3 kB»): hay que convertirlo a KB
function aKB(txt) {
  const m = String(txt || '').match(/([\d.,]+)\s*(bytes|b|kb|mb)/i);
  if (!m) return 0;
  const n = parseFloat(m[1].replace(',', '.'));
  const u = m[2].toLowerCase();
  return u === 'mb' ? n * 1024 : u === 'kb' ? n : n / 1024;
}

const salida = [];

for (const item of $input.all()) {
  const correo = item.json;
  const remitente = correo.from?.value?.[0]?.address || correo.from?.text || 'desconocido';
  const fecha = DateTime.fromISO(new Date(correo.date || Date.now()).toISOString()).toFormat('yyyy-MM-dd');
  const dominio = remitente.split('@')[1]?.split('.')[0] || 'proveedor';

  for (const archivo of Object.values(item.binary || {})) {
    const nombre = (archivo.fileName || '').toLowerCase();
    const esDoc = DOCS_OK.some((e) => nombre.endsWith(e));
    const esImg = IMG_EXT.some((e) => nombre.endsWith(e));
    const imagenValida = esImg && aKB(archivo.fileSize) >= MIN_KB_IMAGEN && !NOMBRES_BASURA.test(nombre);
    if (!esDoc && !imagenValida) continue;

    salida.push({
      json: {
        fecha,
        remitente,
        asunto: correo.subject || '',
        original: archivo.fileName,
        nombreArchivo: fecha + '_' + dominio + '_' + archivo.fileName,
        tipoArchivo: archivo.mimeType,
      },
      // El binario debe seguir llamándose «archivo»: «Subir a Drive» lo busca con ese nombre
      binary: { archivo },
    });
  }
}
return salida;
